//! 🧪️ Prepared native bands preserve original scalar custody and independently funded cancellation.
use super::*;
struct Source<'a>(&'a[f64]);
impl ScalarRankSource for Source<'_>{fn original_identity(&self)->(usize,u64){(self.0.as_ptr()as usize,self.0.len()as u64)}fn len(&self)->usize{self.0.len()}fn value_demand(&self,index:usize)->Result<RetirementDemand,ValueError>{if index>=self.0.len(){return Err(invalid())}Ok(RetirementDemand{copy_bytes:size_of::<f64>()+size_of::<usize>(),depth:1,..Default::default()})}fn value(&self,index:usize)->Result<f64,ValueError>{self.0.get(index).copied().ok_or_else(invalid)}}
fn observe<T>(f:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);(value,(heap.requested_bytes,heap.released_bytes))}
fn close(cursor:&mut ScalarRankCursor,grant:Grant)->(usize,usize){cursor.begin_close();let mut heap=(0,0);for _ in 0..100000{if cursor.terminal_is_empty(){return heap}let(step,h)=observe(||cursor.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));heap.0+=h.0;heap.1+=h.1;}panic!("native scalar rank close did not finish")}
#[test]
fn original_scalar_rank_matches_sqlite_fixture_and_returns_original_pages(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let grant:Grant=serde_json::from_value(law["policy"].clone()).unwrap();let values:Vec<f64>=law["values"].as_array().unwrap().iter().map(|value|value.as_f64().unwrap_or_else(||match value.as_str().unwrap(){"NaN"=>f64::NAN,"Infinity"=>f64::INFINITY,_=>f64::NEG_INFINITY})).collect();let source=Source(&values);let identity=source.original_identity();
 for prefix in law["cancelPrefixes"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as usize).chain(std::iter::once(usize::MAX)){let((mut cursor,receipt),h)=observe(||ScalarRankCursor::admit(law["epsilonFactor"].as_f64().unwrap(),law["bands"].as_u64().unwrap()as u8,grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!(h,(0,0));let mut heap=h;let mut turns=0;
  while !cursor.complete()&&turns<prefix{let demand=cursor.demand(&source).unwrap();for denied in[Grant{maximum_items:0,..grant},Grant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant},Grant{maximum_depth:0,..grant}]{let(step,h)=observe(||cursor.advance(&source,denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));}if demand.capacity_bytes>0{let(step,h)=observe(||cursor.advance(&source,Grant{maximum_capacity_bytes:demand.capacity_bytes-1,..grant}).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(h,(0,0));}let(step,h)=observe(||cursor.advance(&source,grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));heap.0+=h.0;heap.1+=h.1;assert_eq!(source.original_identity(),identity);turns+=1;assert!(turns<100000);}
  if prefix==usize::MAX{let((projection,receipt),h)=observe(||cursor.take(grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!(h,(0,0));for(index,band)in law["expected"].as_array().unwrap().iter().enumerate(){assert_eq!(projection.bands.get(index).copied(),Some(band.as_u64().unwrap()as u8));}assert_eq!((projection.minimum,projection.maximum),(0.,100.));let mut owner=semio_framework_value::retirement::controlled::ControlledRetirement::new(projection).unwrap_or_else(|_|panic!("native rank projection owns its original pages"));while !owner.terminal_is_empty(){let(step,h)=observe(||owner.step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!(h,(step.progress().retained_capacity_bytes,step.progress().released_bytes));heap.0+=h.0;heap.1+=h.1;}assert_eq!(observe(||drop(owner)).1,(0,0));}
  let h=close(&mut cursor,grant);heap.0+=h.0;heap.1+=h.1;assert_eq!(observe(||drop(cursor)).1,(0,0));assert_eq!(heap.0,heap.1);
 }
}
